from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface
from ...exception import BTSSMExecutionError
from ute_common_converter.to_bool import to_bool


class PortSecurityInterface(BaseClToolInterface):

    OPERATION = 'changesecurity'

    def disable_bts_port_security(self, timeout='15min', ignore_state=False, **kwargs):
        """
        Disable BTS port security.

        :param Boolean ignore_state: Determines whether or not to ignore port security state.

        :return: Path(s) of collected file(s) or empty list if port security state error is ignored
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['disable']
        if nolog:
            flags.append('nolog')
        try:
            return self._execute_cl_tool_operation(alias=alias,
                                                   timeout=timeout,
                                                   operation=PortSecurityInterface.OPERATION,
                                                   params=params,
                                                   trs_ip=ne,
                                                   flags=flags)
        except(BTSSMExecutionError) as e:
            if to_bool(ignore_state) and e.rc == 76:
                return []
            raise

    def enable_bts_port_security(self, timeout='15min', ignore_state=False, **kwargs):
        """
        Enable BTS port security.

        :param Boolean ignore_state: Determines whether or not to ignore port security state

        :return: Path(s) of collected file(s) or empty list if port security state error is ignored
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['enable']
        if nolog:
            flags.append('nolog')
        try:
            return self._execute_cl_tool_operation(alias=alias,
                                                   timeout=timeout,
                                                   operation=PortSecurityInterface.OPERATION,
                                                   params=params,
                                                   trs_ip=ne,
                                                   flags=flags)
        except(BTSSMExecutionError) as e:
            if to_bool(ignore_state) and e.rc == 76:
                return []
            raise
